extends SceneTree
## Снимок сцены из Godot (инвариант 10a). Нужно окно, не headless:
##   godot --path . --script tools/screenshot.gd -- --scene res://view/showcase.tscn \
##         --out docs/reviews/x.png [--anim run --t 0.2] [--frames 8]
## Если у сцены есть метод pose(anim, t) — он вызывается перед снимком.

func _initialize() -> void:
	var args := _parse(OS.get_cmdline_user_args())
	var packed := load(args.get("scene", "res://view/app.tscn")) as PackedScene
	var scene := packed.instantiate()
	root.add_child(scene)
	await process_frame  # _ready сцены отрабатывает после _initialize
	if args.has("anim") and scene.has_method("pose"):
		scene.call("pose", args["anim"], float(args.get("t", "0")))
	for i in int(args.get("frames", "8")):
		await process_frame
	var out := str(args.get("out", "tools/out/shot.png"))
	DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path(out).get_base_dir())
	var img := root.get_viewport().get_texture().get_image()
	var err := img.save_png(ProjectSettings.globalize_path(out))
	print("SCREENSHOT %s %dx%d err=%d" % [out, img.get_width(), img.get_height(), err])
	quit(0 if err == OK else 1)


func _parse(a: PackedStringArray) -> Dictionary:
	var d := {}
	var i := 0
	while i < a.size():
		if a[i].begins_with("--") and i + 1 < a.size():
			d[a[i].substr(2)] = a[i + 1]
			i += 2
		else:
			i += 1
	return d

extends GutTest
## Модели из assets/models/ грузятся, масштаб 1 юнит = 1 м (инвариант 13).

const MAGE_HEIGHT := 1.8
const TOL := 0.02


func _aabb(n: Node) -> AABB:
	var box := AABB()
	var first := true
	for m in n.find_children("*", "MeshInstance3D", true, false):
		var mi := m as MeshInstance3D
		if mi.name.begins_with("mage_staff"):  # посох в T-позе покоя торчит вверх — рост считаем без него
			continue
		var b := mi.global_transform * mi.get_aabb()
		box = b if first else box.merge(b)
		first = false
	return box


func test_all_models_load() -> void:
	for name in ["mage", "staff", "wall", "shrine"]:
		var scene := load("res://assets/models/%s.glb" % name) as PackedScene
		assert_not_null(scene, name)


func test_mage_height() -> void:
	var mage := (load("res://assets/models/mage.glb") as PackedScene).instantiate()
	add_child_autofree(mage)
	assert_almost_eq(_aabb(mage).size.y, MAGE_HEIGHT, TOL)


func test_mage_has_three_animations() -> void:
	var mage := (load("res://assets/models/mage.glb") as PackedScene).instantiate()
	add_child_autofree(mage)
	var ap := mage.find_children("*", "AnimationPlayer", true, false)[0] as AnimationPlayer
	for a in ["idle", "run", "dash"]:
		assert_true(ap.has_animation(a), a)
